import{c as t,Q as d,j as o,m as c}from"./chunks/framework.DGHXLY8X.js";const p=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1788066548000}'),a={name:"reference/cli.md"};function r(s,e,n,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>The <code>videonode</code> binary runs the daemon with no subcommand, and exposes a small set of subcommands for validation, schema export, and entity CRUD. This page lists those subcommands and the flags they share.</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th><th>Notable flags</th></tr></thead><tbody><tr><td>(none)</td><td>Start the daemon (HTTP API, RTSP/SRT/WebRTC, pipeline supervisor)</td><td><code>-c, --config</code>, plus every <code>[section]</code> override flag</td></tr><tr><td><code>validate-encoders</code></td><td>Probe H.264 and H.265 encoders and write the results to <code>streams.toml</code></td><td><code>-q, --quiet</code>, <code>--streams-config</code></td></tr><tr><td><code>validate-config</code></td><td>Check <code>streams.toml</code> for dangling upstream refs, layout entries pointing at unknown inputs, ID collisions, and source <code>test_mode</code>/<code>device</code> conflicts</td><td><code>--streams-config</code></td></tr><tr><td><code>openapi</code></td><td>Dump the OpenAPI spec to stdout</td><td></td></tr><tr><td><code>version</code></td><td>Print build version and metadata</td><td><code>--json</code></td></tr><tr><td><code>source list|get|create|delete</code></td><td>CRUD over <code>/api/sources</code></td><td><code>--api-url</code>, <code>--username</code>, <code>--password</code>, <code>-f, --file</code> (create)</td></tr><tr><td><code>composer list|get|create|delete</code></td><td>CRUD over <code>/api/composers</code></td><td><code>--api-url</code>, <code>--username</code>, <code>--password</code>, <code>-f, --file</code> (create)</td></tr><tr><td><code>stream list|get|create|delete</code></td><td>CRUD over <code>/api/streams</code></td><td><code>--api-url</code>, <code>--username</code>, <code>--password</code>, <code>-f, --file</code> (create)</td></tr></tbody></table><p>The <code>source</code>, <code>composer</code>, and <code>stream</code> groups are thin REST clients (<code>cmd/httpclient.go</code>): each subcommand calls the matching endpoint on a running daemon, so it mirrors the documented <a href="./rest-api">REST API</a> rather than adding behavior. <code>create</code> reads its JSON body from <code>--file</code> or stdin; <code>get</code> and <code>delete</code> take the entity id as a positional argument.</p><h2 id="api-client-flags" tabindex="-1">API-client flags <a class="header-anchor" href="#api-client-flags" aria-label="Permalink to &quot;API-client flags&quot;">​</a></h2><p>The CRUD subcommands resolve their target with the same precedence as the rest of the CLI: flag, then environment variable, then default.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Environment variable</th><th>Default</th></tr></thead><tbody><tr><td><code>--api-url</code></td><td><code>VIDEONODE_API_URL</code></td><td><code>http://localhost:8090</code></td></tr><tr><td><code>--username</code></td><td><code>VIDEONODE_USERNAME</code></td><td><code>videonode</code></td></tr><tr><td><code>--password</code></td><td><code>VIDEONODE_PASSWORD</code></td><td><code>videonode</code></td></tr></tbody></table><p>For daemon configuration flags and their env overrides, see the <a href="./config-toml">config.toml reference</a>.</p>',9)])])}const u=t(a,[["render",r]]);export{p as __pageData,u as default};
